settings.custom_css:
.wp-page {
  padding-top: 72px;
}
#header {
  position: fixed;
  left: 0;
  top: 0;
  right: 0;
  z-index: 10;
}
#header.e-con > .e-con-inner {
  max-width: 1320px;
}
#header .elementor-widget-image img {
  width: 110px;
}
#header .elementor-nav-menu__container .elementor-nav-menu {
  flex-wrap: nowrap;
  margin: 0 -18px;
}
#header .elementor-nav-menu__container ul li {
  margin: 0 18px;
}
#header .elementor-nav-menu__container ul li a {
  font-family: Montserrat;
  font-size: 14px;
  font-weight: 600;
  color: rgba(255, 255, 255, 0.6);
  line-height: 20px;
  transition: all .3s;
  overflow: hidden;
  position: relative;
  padding: 11px 0;
}
#header .elementor-nav-menu__container ul li a:hover:before {
  left: 0;
  right: 50%;
}
#header .elementor-nav-menu__container ul li a:hover:after {
  right: 0;
  left: 50%;
}
#header .elementor-nav-menu__container ul li a:before,
#header .elementor-nav-menu__container ul li a:after {
  content: '';
  display: block;
  height: 0;
  border-bottom: 1px solid #fff;
  position: absolute;
  top: 35px;
  transition: all .3s;
}
#header .elementor-nav-menu__container ul li a:before {
  left: -50%;
  right: 150%;
}
#header .elementor-nav-menu__container ul li a:after {
  right: -50%;
  left: 150%;
}
#header .elementor-nav-menu__container ul li.button a,
#header .elementor-nav-menu__container ul li.call a {
  padding: 11px 20px;
}
#header .elementor-nav-menu__container ul li.button a:before,
#header .elementor-nav-menu__container ul li.call a:before,
#header .elementor-nav-menu__container ul li.button a:after,
#header .elementor-nav-menu__container ul li.call a:after {
  display: none;
}
#header .elementor-nav-menu__container ul li.button {
  margin-left: 8px;
}
#header .elementor-nav-menu__container ul li.button a {
  border: 1px solid rgba(255, 255, 255, 0.3);
  color: #fff;
  border-radius: 6px;
}
#header .elementor-nav-menu__container ul li.button a:hover {
  color: #162232;
  background-color: #fff;
}
#header .elementor-nav-menu__container ul li.call {
  margin-right: 8px;
}
#header .elementor-nav-menu__container ul li.call a {
  border: 1px solid #C9A240;
  color: #0F1923;
  border-radius: 6px;
  background-color: #C9A240;
  padding-left: 40px;
  background-image: url(https://rsraingutters.com/wp-content/uploads/2026/05/phone-2.png);
  background-repeat: no-repeat;
  background-size: 16px auto;
  background-position: 20px center;
}
#header .elementor-nav-menu__container ul li.call a:hover {
  background-color: #fff;
  border-color: #fff;
}
#header .elementor-menu-toggle {
  margin: 0;
  position: absolute;
  right: -7px;
  padding: 6px;
  top: 50%;
  margin-top: -17px;
}
#header .elementor-menu-toggle svg {
  fill: #fff;
}
#header .elementor-nav-menu--dropdown {
  position: fixed;
  left: 0;
  right: 0;
  top: 72px;
  margin-top: 0;
  background-color: #162232;
  padding: 0 20px 10px 20px;
}
#header .elementor-nav-menu--dropdown .elementor-nav-menu {
  margin: 0 auto;
  max-width: 270px;
}
#header .elementor-nav-menu--dropdown .elementor-nav-menu li {
  margin: 10px 0;
}
#header .elementor-nav-menu--dropdown .elementor-nav-menu li.button {
  margin-left: 0;
}
#header .elementor-nav-menu--dropdown .elementor-nav-menu li.call {
  margin-right: 0;
}
#header .elementor-nav-menu--dropdown .elementor-nav-menu li.call a {
  background-position: 105px center;
}
#header .elementor-nav-menu--dropdown .elementor-nav-menu li a {
  text-align: center;
  display: block;
}

