    #homehero .elementor-background-video-container{ width:100%; height:750px;
    }
    #homehero .elementor-background-video-container:after{ content:''; display:block; height:120px; position:absolute; top:640px; left:0; right:0; background:linear-gradient(0deg,rgba(24, 34, 47, 1) 0%, rgba(24, 34, 47, 1) 10%, rgba(24, 34, 47, 0) 100%); }
    #homehero{ background-size:auto 750px; background-position:top center; background-repeat:no-repeat; background-color:rgba(24, 34, 47, 1); }
}

