.elementor-widget-nav-menu.footermenu .elementor-nav-menu--main ul li {
  margin: 0 0 12px 0;
}
.elementor-widget-nav-menu.footermenu .elementor-nav-menu--main ul li a.elementor-item {
  font-family: "Open Sans";
  font-size: 13px;
  padding: 0;
  font-weight: 400;
  color: rgba(255, 255, 255, 0.5);
  text-decoration: underline;
  transition: all .3s;
}
.elementor-widget-nav-menu.footermenu .elementor-nav-menu--main ul li a.elementor-item:hover {
